        std::cerr << "Не удалось открыть файл: " << filename << std::endl;
        return -1;
    }

    std::string line;
    int count = 0;
    while (getline(file, line)) {
        std::istringstream iss(line);
        std::string temp;
        while (iss >> temp) {
            if (temp == word) {
                count++;
            }
        }
    }

    file.close();
    return count;
}

int main() {
